import{_ as a,o as t,c as o,ae as r}from"./chunks/framework.Czhw_PXq.js";const m=JSON.parse('{"title":"ADR 034: Global Theme Strategy and Glassmorphism UI","description":"","frontmatter":{},"headers":[],"relativePath":"adr/034-global-theme-strategy.md","filePath":"adr/034-global-theme-strategy.md"}'),s={name:"adr/034-global-theme-strategy.md"};function i(l,e,n,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-034-global-theme-strategy-and-glassmorphism-ui" tabindex="-1">ADR 034: Global Theme Strategy and Glassmorphism UI <a class="header-anchor" href="#adr-034-global-theme-strategy-and-glassmorphism-ui" aria-label="Permalink to &quot;ADR 034: Global Theme Strategy and Glassmorphism UI&quot;">​</a></h1><p>Date: 2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The initial application design had inconsistent styling between the Landing Page (Light Mode, &quot;Crema&quot; palette) and the Dashboard/Auth pages (Dark Mode by default). This created a disjointed user experience. Users expected the premium, accessible aesthetic of the Landing Page to persist throughout the application, while also retaining the option for a Dark Mode for low-light environments.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have adopted a <strong>Global Theme Strategy</strong> with a <strong>Glassmorphism</strong> design language.</p><h3 id="_1-global-theme-provider" tabindex="-1">1. Global Theme Provider <a class="header-anchor" href="#_1-global-theme-provider" aria-label="Permalink to &quot;1. Global Theme Provider&quot;">​</a></h3><ul><li>We use a React Context (<code>ThemeContext</code>) to manage <code>light</code> and <code>dark</code> modes globally.</li><li>The theme state is persisted in <code>localStorage</code> to remember user preference.</li><li>The default mode matches the system preference (<code>prefers-color-scheme</code>) but defaults to <code>light</code> to showcase the premium brand aesthetic.</li></ul><h3 id="_2-design-system-glassmorphism" tabindex="-1">2. Design System: Glassmorphism <a class="header-anchor" href="#_2-design-system-glassmorphism" aria-label="Permalink to &quot;2. Design System: Glassmorphism&quot;">​</a></h3><p>We utilize a &quot;Glassmorphism&quot; aesthetic to create depth and hierarchy.</p><ul><li><strong>Background</strong>: A complex mesh gradient (<code>from-[#E8E6DE] via-[#D3D0C2] to-[#B8C1B7]</code>) provides a rich, tactile feel in Light Mode. Dark mode uses deep charcoal gradients.</li><li><strong>Cards</strong>: UI elements use semi-transparent white backgrounds with backdrop blur (<code>backdrop-blur-3xl</code>, <code>bg-white/30</code>) and subtle white borders (<code>border-white/50</code>).</li><li><strong>Shadows</strong>: Soft, colored shadows (<code>shadow-[0_20px_50px_rgba(31,38,135,0.1)]</code>) lift elements off the page.</li></ul><h3 id="_3-typography-and-color-palette" tabindex="-1">3. Typography and Color Palette <a class="header-anchor" href="#_3-typography-and-color-palette" aria-label="Permalink to &quot;3. Typography and Color Palette&quot;">​</a></h3><ul><li><strong>Fonts</strong>: <em>Playfair Display</em> for headings (serif, trustworthy) and <em>Inter</em> for body text (sans-serif, legible).</li><li><strong>Colors</strong>: <ul><li><strong>Brand</strong>: Deep Charcoal (<code>#2D312D</code>) for text.</li><li><strong>Action</strong>: Emerald Green (<code>emerald-600</code>) for primary buttons.</li><li><strong>Accent</strong>: Gold (<code>#C5A028</code>) for highlights.</li></ul></li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Consistency</strong>: The user experiences a seamless visual journey from Landing Page to Dashboard.</li><li><strong>Perceived Value</strong>: The premium aesthetic aligns with the professional nature of the tool (Tender Analysis).</li><li><strong>Accessibility</strong>: High contrast is maintained in both modes; the light mode avoids harsh white backgrounds.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Complexity</strong>: CSS/Tailwind classes are more verbose due to the <code>dark:</code> modifiers and complex gradients.</li><li><strong>Performance</strong>: Heavy use of <code>backdrop-blur</code> can be performance-intensive on very low-end devices (mitigated by CSS hardware acceleration).</li></ul>',20)])])}const p=a(s,[["render",i]]);export{m as __pageData,p as default};
